# This script is for the data preparation for the R 
library(R.matlab)
library(NeuroMyelFC)
library(reshape2)
library(afex)

# MacOS
setwd("~/projects/FrequencySliding/")

# windows
setwd("C:/Users/kaank/OneDrive/Belgeler/GitHub/FrequencySliding/")
dat <- read.csv("./data/output/MF_indexed.csv") %>% 
  as.data.frame() %>% mutate(
    group = factor(group),
    Sex = factor(Sex)
  )
library(brms)
library(bayesplot)
f_BDI <- bf(
  BDI_z ~ unimodal_z + transmodal_z + group + Sex + age_z +        # mean slopes
    unimodal_z:group + transmodal_z:group,                   # allow slopes to differ by group
  sigma ~ 0 + group,                                         # ??_BP , ??_HC
  nu    ~ 0 + group                                                # ??_BP , ??_HC
)

priors <- c(
  prior(normal(0, 0.50),            class = "Intercept"),          # mean intercept
  prior(normal(0, 0.30),            class = "b"),                 # all mean slopes & interactions
  prior(normal(0, 0.30),            class = "b", dpar = "sigma"), # log-?? coefficients (one per group)
  prior(normal(log(10), 0.50),      class = "b", dpar = "nu")     # log-?? coefficients (one per group)
)

fit_grp <- brm(
  formula = f_BDI,
  data    = dat,
  family  = student(),          # enables ?? & ?? sub-models
  prior   = priors,
  chains  = 4, iter = 4000, cores = 4,
  seed    = 123
)

## ??????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
## 4.  Posterior-predictive check by group (should capture the two peaks)
## ??????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????

fit_grp_prior <- update(fit_grp, sample_prior = "only")  # runs the only prior
pp_check(fit_grp_prior, ndraws = 1e2) + ggtitle("PRIOR")

fit_grp
pp_check(fit_grp, type = "dens_overlay_grouped",
         group = "group", ndraws = 1e2) + ggtitle("POSTERIOR")


pp_check(fit_grp, type = "error_scatter_avg")

posterior <- as_draws_df(fit_grp)
mcmc_areas(
  posterior, # Extract posterior draws
  pars =  names(posterior)[1:13],
  prob = 0.95
) 